var EXTRA=[{"dot": "gray", "j": "Curr Rev Musculoskelet Med", "h": "Stato dell'arte sul LCA: innesto, rinforzo laterale e rientro a criteri", "v": "Revisione narrativa che include il protocollo riabilitativo dell'autore senior; riassume la letteratura, non porta dati nuovi.", "pmid": "42873380", "doi": "10.1007/s12178-026-10060-9", "temi": ["LCA", "innesto quadricipitale", "tenodesi laterale", "criteri di rientro"]}, {"dot": "gray", "j": "Acta Orthop", "h": "Protesi che conserva entrambi i crociati: fissazione simile alla tradizionale a lungo termine", "v": "RCT con radiostereometria su gruppi piccoli; le revisioni compaiono solo nel braccio sperimentale, quindi non si può escludere una differenza.", "pmid": "42770474", "doi": "10.2340/17453674.2026.46805", "temi": ["protesi totale", "bicrociata", "radiostereometria"]}, {"dot": "gray", "j": "Front Sports Act Living", "h": "Dopo il LCA con hamstring la quota che supera i test di rientro varia molto da prova a prova", "v": "Serie consecutiva di un centro con protocollo riabilitativo standard; nessun fattore spiega chi passa; l'innesto è l'hamstring, non il tuo.", "pmid": "42877658", "doi": "10.3389/fspor.2026.1922271", "temi": ["LCA", "test di rientro", "simmetria degli arti"]}, {"dot": "gray", "j": "J Arthroplasty", "h": "Revisione di protesi di ginocchio: steli in titanio a più offset contro steli standard", "v": "Coorte retrospettiva su gruppi piccoli: punteggi simili, meno dolore alla punta dello stelo con il titanio; tocca la protesi di revisione, non la tua pratica abituale.", "pmid": "42887706", "doi": "10.1016/j.arth.2026.10.006", "temi": ["revisione protesica", "steli", "protesi totale"]}, {"dot": "gray", "j": "Arthroscopy", "h": "Ricostruire solo il legamento quadricipito-femorale mediale può bastare, se l'innesto è ben posizionato", "v": "Commento editoriale: opinione di esperti sull'instabilità rotulea, senza dati nuovi.", "pmid": "42852527", "doi": "10.1002/arj.70645", "temi": ["instabilità rotulea", "MPFL", "legamento quadricipito-femorale"]}, {"dot": "gray", "j": "J Knee Surg", "h": "Fratture-lussazioni del piatto tibiale mediale: nelle immagini compare un pattern da lesione rotatoria tipo LCA", "v": "Serie radiologica retrospettiva su pochi casi, senza esiti clinici; il pattern è solo descrittivo.", "pmid": "42887883", "doi": "10.1055/a-2982-7510", "temi": ["frattura del piatto tibiale", "lesione rotatoria", "menisco"]}, {"dot": "gray", "j": "Arch Orthop Trauma Surg", "h": "Tutori per il legamento collaterale mediale: grande variabilità nella resistenza al valgo", "v": "Prova su banco con un modello meccanico; il confronto fra categorie è esplorativo e non dice nulla sugli esiti dei pazienti.", "pmid": "42802206", "doi": "10.1007/s00402-026-06519-6", "temi": ["LCM", "tutore", "valgo"]}, {"dot": "gray", "j": "J Clin Med", "h": "Distanza fibula-tibia e revisione per instabilità dopo protesi: un marcatore radiografico ancora da validare", "v": "Caso-controllo esplorativo con pochi pazienti; la rotazione della radiografia può confondere, non è un criterio per decidere.", "pmid": "42882119", "doi": "10.3390/jcm15197658", "temi": ["protesi totale", "instabilità", "radiografia"]}, {"dot": "gray", "j": "J Orthop Res", "h": "Dopo chirurgia del ginocchio il corpo adiposo infrapatellare è più piccolo nelle corritrici, non nei corridori", "v": "Analisi secondaria esplorativa trasversale; il volume non risulta legato ai sintomi femororotulei.", "pmid": "42885727", "doi": "10.1002/jor.70300", "temi": ["corpo adiposo infrapatellare", "chirurgia del ginocchio", "corsa"]}, {"dot": "gray", "j": "Clin Orthop Surg", "h": "Allineamento cinematico nella protesi di ginocchio: i limiti all'applicazione universale", "v": "Revisione narrativa critica: elenca i problemi aperti (allentamento in varo, valgo severo, classificazione CPAK) senza dati nuovi.", "pmid": "42876852", "doi": "10.4055/cios25336", "temi": ["protesi totale", "allineamento cinematico", "CPAK"]}];
var SCOPERTE=[{"t": "Cellule e scaffold per l'artrosi: come tre prodotti approvati hanno percorso la strada regolatoria", "v": "Confronto fra CARTISTEM, JACC e MACI per origine cellulare, uso dello scaffold e requisiti di evidenza richiesti. Vale la deviazione perché tocca la famiglia delle matrici e delle cellule che usi in AMIC e AutoCart, vista dal lato di chi le autorizza; è un'analisi regolatoria, senza dati di esito sui pazienti.", "pmid": "42859758", "doi": "10.1016/j.reth.2026.101177", "temi": ["cartilagine", "scaffold", "terapie cellulari", "regolatorio"]}, {"t": "Un robot cinese a piattaforma aperta per la protesi monocompartimentale: precisione sotto il millimetro su ossa sintetiche", "v": "Studio esplorativo su ossa sintetiche: due studenti non esperti hanno eseguito venti interventi ciascuno con un sistema non legato a un solo produttore di impianti, senza una curva di apprendimento visibile. Vale la deviazione perché è il filone robotico visto da un attore asiatico; non sono pazienti e le differenze fra operatori non sono separabili.", "pmid": "42865385", "doi": "10.3389/frobt.2026.1886514", "temi": ["robotica", "protesi monocompartimentale", "piattaforma aperta", "Cina"]}, {"t": "Idrogel che imita il menisco, con cellule staminali sinoviali, per le lesioni della zona rossa e rosso-bianca", "v": "Scaffold anisotropo con succinato per regolare il metabolismo cellulare, testato in vitro e nel coniglio: favorisce una riparazione di tipo fibrocartilagineo e attenua la degenerazione della cartilagine. Vale la deviazione perché mostra dove sta andando la bioingegneria della sutura meniscale; è un modello animale, lontano dalla clinica.", "pmid": "42853095", "doi": "10.1021/acsbiomaterials.6c00999", "temi": ["menisco", "idrogel", "cellule staminali", "bioingegneria"]}];
var SOC={"1": {"video": "Ricostruzione del legamento collaterale mediale del ginocchio: meglio un tendine di donatore o uno prelevato dal paziente? Una revisione di sedici studi, pubblicata a settembre 2026, mostra che in entrambi i casi la funzione migliora in modo significativo. Le complicanze riportate sono l'11,2% con il tendine di donatore e il 4,0% con quello del paziente.\n\nIl limite: i due gruppi vengono da studi diversi e nessuno li confronta direttamente, quindi non si può dire quale sia superiore.\nFonte: PubMed, PMID 42770603.", "linkedin": "Ricostruzione del LCM: allotrapianto d'Achille o autotrapianto di hamstring? Revisione sistematica (KSSTA, settembre 2026; 16 studi, 107 e 275 pazienti): PROMs migliorati in modo significativo in entrambi i gruppi; complicanze 11,2% contro 4,0%.\n\nLimiti: sintesi narrativa di serie diverse, confronto indiretto, evidenza giudicata insufficiente dagli autori per dichiarare la superiorità di un innesto; testo completo non aperto.\nFonte: PubMed, PMID 42770603.", "instagram": "Legamento collaterale mediale: due tendini possibili.\nUna revisione di sedici studi: in entrambi i casi il ginocchio migliora.\nLe complicanze sono state un po' più frequenti con il tendine di donatore, ma gli studi non si confrontano direttamente.\nFonte: PubMed, PMID 42770603.", "pazienti": "Quando il legamento collaterale mediale del ginocchio va ricostruito, si può usare un tendine di donatore oppure un tendine prelevato dal paziente stesso. Una revisione di sedici studi, pubblicata a settembre 2026, mostra che in entrambi i casi la funzione del ginocchio migliora in modo significativo; le complicanze riportate sono state un po' più frequenti con il tendine di donatore.\n\nGli studi non mettono a confronto i due tendini nella stessa popolazione, quindi non indicano quale sia preferibile: la scelta si discute con il chirurgo, caso per caso.\nFonte: PubMed, PMID 42770603."}};
var SOCV={"1": {"video": {"chir": ["Ricostruzione del legamento collaterale mediale: allotrapianto di tendine d'Achille o autotrapianto di hamstring? Una revisione sistematica, pubblicata su Knee Surgery, Sports Traumatology, Arthroscopy a settembre 2026, ha incluso sedici studi: sei con allotrapianto, centosette pazienti, e dieci con hamstring, duecentosettantacinque pazienti. In entrambi i gruppi i punteggi riferiti dal paziente migliorano in modo significativo.", "Le complicanze sono l'undici virgola due per cento con l'allotrapianto e il quattro per cento con l'hamstring: due fallimenti dell'innesto contro uno, tre infezioni contro una. Ma sono serie diverse, di centri e periodi diversi, la sintesi è solo narrativa e nessuno studio confronta direttamente i due innesti.", "Il limite: gli autori stessi parlano di evidenza indiretta e insufficiente per dichiarare la superiorità di uno dei due. Fissazione, trattamento del tessuto e fase della lesione non compaiono nell'abstract e il testo completo non è stato aperto. Per la pratica: l'allotrapianto resta un'opzione documentata, con un segnale numerico di più complicanze che questo lavoro non dimostra.\nFonte: PubMed, PMID 42770603."], "misto": ["Il legamento collaterale mediale, quando va ricostruito, può esserlo con un tendine di donatore, quello d'Achille, oppure con un tendine prelevato dal paziente, l'hamstring. Una revisione di sedici studi, pubblicata a settembre 2026, ha messo insieme i risultati dei due metodi e trova un miglioramento significativo dei punteggi funzionali in entrambi.", "Le complicanze riportate sono l'undici virgola due per cento con il tendine di donatore e il quattro per cento con l'hamstring. Le cifre vengono però da serie di centri diversi, e nessuno studio ha confrontato direttamente i due tendini.", "Il limite: gli autori stessi scrivono che l'evidenza è indiretta e non basta per dire quale tendine sia superiore. Il testo completo non è stato aperto.\nFonte: PubMed, PMID 42770603."], "pazienti": ["Se il legamento collaterale mediale del ginocchio va ricostruito, si può usare un tendine di donatore oppure un tendine prelevato dal paziente stesso, nella parte posteriore della coscia. Una revisione di sedici studi, pubblicata a settembre 2026, mostra che in entrambi i casi la funzione del ginocchio migliora in modo significativo.", "Le complicanze riportate sono state un po' più frequenti con il tendine di donatore, undici su cento contro quattro su cento. Ma i dati vengono da studi diversi, che non mettono a confronto i due tendini nella stessa popolazione.", "Per questo non è possibile dire quale tendine sia preferibile in assoluto. La scelta si discute con il chirurgo, caso per caso, in base alla lesione e alla storia di ciascuno.\nFonte: PubMed, PMID 42770603."]}, "linkedin": {"chir": ["Ricostruzione del LCM: allotrapianto d'Achille contro autotrapianto di hamstring (KSSTA, settembre 2026). Revisione sistematica PRISMA di 16 studi, 107 e 275 pazienti, sintesi narrativa; PROMs migliorati in entrambi (IKDC medio 81,1 contro 78,8; Lysholm 86,8 contro 87,2).", "Complicanze 11,2% con allotrapianto (2 fallimenti, 4 instabilità in valgo residue, 3 infezioni) contro 4,0% con hamstring (1 fallimento, 4 instabilità in valgo, 1 infezione).", "Limiti: serie diverse senza confronto diretto, sintesi non quantitativa, fissazione e tessuto non descritti nell'abstract; gli autori giudicano l'evidenza indiretta e insufficiente per la superiorità. Testo completo non aperto.\nFonte: PubMed, PMID 42770603."], "misto": ["Ricostruzione del legamento collaterale mediale: tendine di donatore o tendine del paziente? Una revisione di 16 studi (settembre 2026) trova un miglioramento funzionale significativo con entrambi.", "Le complicanze riportate sono l'11,2% con il tendine di donatore e il 4,0% con quello del paziente.", "Limite: il confronto è indiretto, fra serie di centri diversi; gli autori non lo ritengono sufficiente per dire quale sia superiore.\nFonte: PubMed, PMID 42770603."], "pazienti": ["Legamento collaterale mediale: per ricostruirlo si può usare un tendine di donatore o uno prelevato dal paziente.", "Una revisione di 16 studi mostra che la funzione migliora con entrambi; le complicanze sono state un po' più frequenti con il tendine di donatore.", "I dati non confrontano i due tendini nella stessa popolazione: la scelta si discute con il chirurgo.\nFonte: PubMed, PMID 42770603."]}, "instagram": {"chir": ["LCM: allotrapianto d'Achille o hamstring?", "Revisione di 16 studi: PROMs migliorati in entrambi; complicanze 11,2% contro 4,0%.", "Confronto indiretto, evidenza insufficiente per la superiorità.\nFonte: PubMed, PMID 42770603."], "misto": ["Legamento collaterale mediale: due tendini a confronto.", "Revisione di 16 studi: la funzione migliora con entrambi; complicanze 11,2% contro 4,0%.", "Il confronto è indiretto, senza un vincitore.\nFonte: PubMed, PMID 42770603."], "pazienti": ["Legamento collaterale mediale: due tendini possibili.", "In 16 studi il ginocchio migliora con entrambi; qualche complicanza in più con il tendine di donatore.", "Gli studi non li confrontano direttamente: se ne parla col chirurgo.\nFonte: PubMed, PMID 42770603."]}, "reel": {"chir": ["LCM: allotrapianto o hamstring?", "16 studi, PROMs migliori in entrambi; complicanze 11,2% contro 4,0%.", "Confronto indiretto, nessuna superiorità dimostrata.\nFonte: PubMed, PMID 42770603."], "misto": ["Collaterale mediale: quale tendine?", "Funzione migliore con entrambi; più complicanze con il donatore, ma confronto indiretto.", "Nessun vincitore dimostrato.\nFonte: PubMed, PMID 42770603."], "pazienti": ["Legamento collaterale: due tendini.", "Il ginocchio migliora con entrambi; i dati non li confrontano.", "Se ne parla col chirurgo.\nFonte: PubMed, PMID 42770603."]}}};
var TAGS={"1": {"linkedin": "#Ortopedia #Ginocchio #MedicinaDelloSport", "instagram": "#ortopedia #ginocchio #legamentocollaterale #chirurgiadelginocchio #medicinadellosport #ortopediaticino #ticino #medicinabasatasulleprove #salute", "kw": "legamento collaterale mediale, ricostruzione, allotrapianto, hamstring, ginocchio"}};
var NLB={"1": {"prof": ["LCM: allotrapianto d'Achille o hamstring? Più complicanze con l'allotrapianto, ma confronto indiretto", "Revisione sistematica (KSSTA, settembre 2026; 16 studi, 107 pazienti con allotrapianto d'Achille e 275 con autotrapianto di hamstring): i punteggi riferiti migliorano in modo significativo in entrambi i gruppi (IKDC medio 81,1 contro 78,8; Lysholm 86,8 contro 87,2), le complicanze sono l'11,2% con l'allotrapianto e il 4,0% con l'hamstring.", "Nota critica: sintesi solo narrativa di serie diverse, nessun confronto diretto fra gli innesti; gli autori stessi giudicano l'evidenza indiretta e insufficiente per dichiarare la superiorità di uno dei due. Testo completo non aperto."], "mix": ["Ricostruzione del legamento collaterale mediale: due tipi di innesto a confronto, senza un vincitore", "Una revisione di sedici studi ha confrontato il tendine d'Achille di donatore con il tendine prelevato dallo stesso paziente (hamstring) per ricostruire il legamento collaterale mediale del ginocchio. In entrambi i casi i punteggi funzionali migliorano in modo significativo; le complicanze riportate sono l'11,2% con il tendine di donatore e il 4,0% con l'hamstring.", "Nota sul limite: i due gruppi vengono da serie di centri diversi e nessuno studio li confronta direttamente, quindi non si può dire che un innesto sia superiore all'altro."], "paz": ["Legamento collaterale mediale: due tendini possibili, entrambi migliorano il ginocchio", "Quando il legamento collaterale mediale del ginocchio va ricostruito, si può usare un tendine di donatore oppure un tendine prelevato dal paziente stesso, nella parte posteriore della coscia. Una revisione di sedici studi mostra che in entrambi i casi la funzione del ginocchio migliora; le complicanze riportate sono state un po' più frequenti con il tendine di donatore.", "Gli studi non confrontano i due tendini nella stessa popolazione, quindi non è possibile dire quale sia preferibile: la scelta si discute con il chirurgo, caso per caso."], "kw": "legamento collaterale mediale, ricostruzione, ginocchio, allotrapianto"}, "2": {"prof": ["Lesione radiale obliqua del menisco laterale nel LCA: la sutura laterale-laterale riduce l'estrusione", "Coorte retrospettiva di Hirosaki (JEO, settembre 2026; livello III): 34 lesioni radiali oblique suturate laterale-laterale e 27 lesioni longitudinali suturate all-inside durante il LCA; estrusione coronale preoperatoria 1,71±1,31 contro 0,32±0,61 mm (p<0,001), ridotta di circa 0,6 mm e simile fra i gruppi a un anno, con esiti clinici simili.", "Nota critica: il confronto è fra due tipi di lesione e non fra due terapie della stessa lesione; 34 contro 27 pazienti, quindi «simile» non è equivalenza; rotture della sutura e reinterventi non nell'abstract."], "mix": ["Strappo del menisco laterale durante il crociato: la sutura riporta il menisco quasi dov'era", "In un gruppo di pazienti operati di legamento crociato anteriore, alcuni avevano una lesione radiale obliqua del menisco laterale, trattata con una sutura da un lato all'altro. Un anno dopo il menisco sporgeva meno dall'articolazione, a livelli simili a quelli di chi aveva un'altra lesione suturata, e i risultati clinici erano simili.", "Nota sul limite: i gruppi sono piccoli (34 e 27 pazienti) e il confronto non riguarda un'altra terapia della stessa lesione, quindi non dice se la sutura sia preferibile a un'alternativa."], "paz": ["Menisco laterale suturato insieme al crociato: dopo un anno il menisco sporge meno", "Durante l'operazione al legamento crociato anteriore può capitare di trovare una lesione del menisco laterale. In uno studio giapponese, chi aveva una lesione di questo tipo e l'ha avuta suturata ha mostrato, a un anno, un menisco meno sporgente e risultati clinici simili a quelli di chi aveva un'altra lesione meniscale suturata.", "Lo studio è piccolo e riguarda un solo centro: non indica quale trattamento sia adatto a ogni persona, che si decide con il chirurgo."], "kw": "menisco laterale, sutura meniscale, legamento crociato, estrusione"}, "3": {"prof": ["Slope tibiale su cadavere: pendenza laterale e traslazione anteriore, differenza laterale-mediale e rotazione", "Studio biomeccanico (AJSM, settembre 2026; 8 ginocchia di cadavere, carico di 500 N): +10° di pendenza tibiale posteriore laterale aumenta la traslazione tibiale anteriore (p=0,012), quella mediale no (p>0,99); +10° di differenza laterale-mediale dà 7,6° di rotazione interna in più a 0° di flessione (p=0,015).", "Nota critica: otto preparati, due angoli di flessione, carico statico, nessun paziente; la correzione differenziale della slope è un'ipotesi degli autori, mai provata clinicamente."], "mix": ["Pendenza del piatto tibiale: la parte laterale decide quanto la tibia scivola in avanti", "In un esperimento su ginocchia di cadavere, i ricercatori hanno modificato separatamente l'inclinazione del lato interno e di quello esterno del piatto tibiale. Aumentare l'inclinazione esterna fa scivolare la tibia più in avanti; è la differenza fra le due inclinazioni a determinare quanto la tibia ruota.", "Nota sul limite: sono otto ginocchia di cadavere, senza muscoli né pazienti; i risultati non dicono ancora come correggere l'inclinazione in sala operatoria."], "paz": ["Inclinazione della tibia e stabilità del ginocchio: un esperimento di laboratorio", "La parte alta della tibia ha una leggera inclinazione all'indietro. In un esperimento su ginocchia di cadavere si è visto che modificarla sul lato esterno cambia quanto la tibia scivola in avanti, mentre la differenza fra lato interno ed esterno cambia quanto ruota.", "È uno studio di laboratorio su otto ginocchia: non si tratta di una cura e non dice che cosa fare in un singolo caso, che si valuta con il chirurgo."], "kw": "slope tibiale, pendenza tibiale, legamento crociato, osteotomia"}, "4": {"prof": ["Osteotomia tibiale alta aperta: progressione femororotulea nel 55,4%, senza effetto sugli esiti rotulei", "Coorte retrospettiva di Fukuoka (Arthroscopy, settembre 2026; livello IV; 168 ginocchia, follow-up medio 12,2 anni): sopravvivenza a 10 anni 91,3%, progressione femororotulea nel 55,4% (93/168), KOOS-femororotuleo 68,5 contro 69,8 (p=0,533) e punteggio HSS 89,0 contro 91,0 (p=0,179); predittori l'angolo di correzione (OR 1,361; p=0,004) e il grado preoperatorio (OR 0,241; p=0,002).", "Nota critica: retrospettivo, senza gruppo non operato, progressione misurata con un salto di grado Kellgren-Lawrence; intervalli di confidenza degli OR non nell'abstract."], "mix": ["Osteotomia della tibia: il ginocchio davanti peggiora alla radiografia, ma i sintomi non cambiano", "In 168 ginocchia seguite in media per oltre dodici anni dopo un'osteotomia tibiale alta, l'artrosi dell'articolazione fra rotula e femore è peggiorata alla radiografia in più della metà dei casi. I punteggi dei sintomi di quella zona, però, erano simili tra chi era peggiorato e chi no.", "Nota sul limite: lo studio è retrospettivo e non ha un gruppo di confronto non operato, quindi non dice quanto sarebbe peggiorata l'articolazione senza intervento."], "paz": ["Dopo l'osteotomia della tibia, la radiografia davanti può peggiorare senza peggiorare i sintomi", "Dopo un'osteotomia per allineare la gamba, l'articolazione fra rotula e femore può mostrare più usura alla radiografia. In uno studio su 168 ginocchia seguite per oltre dodici anni, questo peggioramento radiografico non si è accompagnato a più dolore o a una funzione peggiore in quella zona.", "Sono dati di un gruppo di pazienti: la situazione di ciascuno dipende dal suo ginocchio e si discute con il chirurgo."], "kw": "osteotomia tibiale alta, artrosi femororotulea, ginocchio varo, lungo termine"}, "5": {"prof": ["Instabilità rotulea e displasia trocleare: la sTTTG preoperatoria prevede esiti dopo MPFL e troclearplastica", "Coorte retrospettiva (Arthroscopy, settembre 2026; livello IV; 101 pazienti, follow-up medio 32,3 mesi): una sTTTG più alta si associa a BPII 2.0 più alto (β=0,98; p=0,019) e a meno dolore (β=-0,10; p=0,048), anche dopo correzione per i confondenti (BPII 2.0 β=0,91; p=0,037).", "Nota critica: R² corretti 0,03-0,06, quindi la sTTTG spiega al più il 6% degli esiti; retrospettivo, solo displasia di alto grado, nessun gruppo con solo MPFL o con sola troclearplastica."], "mix": ["Rotula che si lussa: una misura sulla risonanza è legata ai risultati dopo l'intervento, ma spiega poco", "In 101 pazienti con lussazioni ricorrenti della rotula e una troclea poco profonda, operati con ricostruzione del legamento che trattiene la rotula e approfondimento della troclea, una distanza misurata sulla risonanza prima dell'intervento era legata a esiti un po' più favorevoli: meno dolore e funzione migliore.", "Nota sul limite: la misura spiega meno del 6% delle differenze fra i pazienti, quindi non permette di scegliere l'intervento."], "paz": ["Lussazione della rotula: una misura sulla risonanza e il risultato dell'operazione", "In pazienti con rotula che si lussa ripetutamente e una troclea poco profonda, operati su entrambi i fronti, una misura presa sulla risonanza prima dell'operazione è risultata legata al dolore e alla funzione dopo l'intervento.", "L'effetto è piccolo e non permette di prevedere il risultato nel singolo caso: la valutazione è fatta con il chirurgo."], "kw": "lussazione rotula, MPFL, troclea, instabilità rotulea"}, "6": {"prof": ["Protesi di ginocchio robotica: la sensibilità al dolore pesa più dell'allineamento sugli esiti a 2 anni", "Sottostudio di un RCT (J Arthroplasty, settembre 2026; 244 TKA robotiche, allineamento funzionale contro meccanico): il Pain Sensitivity Questionnaire predice FJS (p=0,02) e OKS (p<0,01), l'allineamento no; nei pazienti a bassa sensibilità FJS 74,9±25,8 contro 61,9±31,4 (p=0,03), nei pazienti ad alta sensibilità 66,8±25,0 contro 65,8±29,5 (p=0,80).", "Nota critica: analisi di sottogruppo esplorative, senza correzione per confronti multipli né IC nell'abstract; marca del robot non riportata."], "mix": ["Protesi di ginocchio con robot: conta di più quanto il paziente è sensibile al dolore che il tipo di allineamento", "In 244 pazienti operati di protesi di ginocchio con un robot, assegnati a caso a due modi di allineare la protesi, la sensibilità al dolore misurata prima dell'intervento ha influenzato i risultati a due anni più del tipo di allineamento. Solo nei pazienti poco sensibili il metodo funzionale ha dato un punteggio più alto.", "Nota sul limite: i confronti nei sottogruppi sono esplorativi e vanno confermati; l'abstract non dice quale robot sia stato usato."], "paz": ["Protesi di ginocchio con robot: la sensibilità al dolore conta nei risultati", "In uno studio su 244 pazienti con protesi di ginocchio eseguita con l'aiuto di un robot, il modo di allineare la protesi ha avuto meno peso nei risultati a due anni rispetto a quanto la persona era sensibile al dolore prima dell'intervento.", "È un'analisi esplorativa, che richiede conferme: non indica quale scelta sia adatta a una persona, che si decide con il chirurgo."], "kw": "protesi di ginocchio, chirurgia robotica, dolore, allineamento"}, "7": {"prof": ["Lesioni multilegamentose del ginocchio in età pediatrica: revisione di 4 studi su 142 pazienti", "Revisione sistematica (J Knee Surg, ottobre 2026; livello IV; 4 studi, 142 pazienti ≤18 anni): origine sportiva nel 70,6% (96/136), angolo posterolaterale coinvolto nel 71,1%, LCP nel 66,2% e LCA nel 57,7%; ricostruzione nella quasi totalità dei LCP e dei LCA, riparazione nel 38,7% dei LCM; complicanze nel 36% (19/53) e revisione nel 7,5% (4/53).", "Nota critica: pochi studi, età da 6 a 18 anni, complicanze note per 53 pazienti su 142, nessun confronto fra riparazione e ricostruzione."], "mix": ["Ginocchio con più legamenti lesi nei ragazzi: le cause sono spesso sportive e le complicanze non rare", "Una revisione di quattro studi su 142 ragazzi di età fino a 18 anni con più legamenti del ginocchio lesi mostra che la causa è spesso lo sport. Quasi tutti i legamenti crociati sono stati ricostruiti; complicanze come la rigidità sono state riportate nel 36% dei 53 pazienti con questo dato.", "Nota sul limite: gli studi sono pochi e di età diverse (da 6 a 18 anni), e non permettono di confrontare i diversi tipi di intervento."], "paz": ["Più legamenti lesi nel ginocchio di un ragazzo: che cosa dice la letteratura", "Le lesioni di più legamenti del ginocchio nei ragazzi sono rare e spesso legate allo sport. Una revisione di quattro studi ha raccolto 142 casi: nella maggior parte i legamenti sono stati ricostruiti e in alcuni sono comparse complicanze, per esempio la rigidità del ginocchio.", "I dati sono pochi e di età molto diverse: la situazione di ciascun ragazzo si valuta caso per caso con il chirurgo."], "kw": "lesioni multilegamentose, ginocchio, ragazzi, legamento crociato"}, "8": {"prof": ["Testosterone e LCA: terapia sostitutiva e rottura a 2 anni, OR 2,83, con eterogeneità del 95,4%", "Revisione sistematica e metanalisi (Sports Health, ottobre 2026; livello III; 7 studi, 1.178.891 pazienti): la terapia sostitutiva con testosterone si associa a più rotture primarie del LCA entro 2 anni (OR 2,83; IC 95% 1,74-4,62), non a più revisioni (OR 1,04; IC 95% 0,84-1,29).", "Nota critica: eterogeneità del 95,4% sulla stima principale, studi osservazionali con confondimento per indicazione, orizzonte di 2 anni; l'OR cumulato non è una stima di un unico effetto."], "mix": ["Terapia con testosterone e crociato: più rotture a due anni, ma gli studi sono molto diversi fra loro", "Una revisione di sette studi su oltre un milione di persone ha trovato che chi assume testosterone come terapia sostitutiva ha avuto più rotture del legamento crociato anteriore nei due anni successivi; non sono invece aumentate le nuove operazioni dopo la ricostruzione.", "Nota sul limite: i sette studi danno risultati molto diversi fra loro e sono osservazionali, quindi non si può dire che la terapia causi le rotture."], "paz": ["Testosterone e legamento crociato: un'associazione da interpretare con prudenza", "Una revisione di studi su oltre un milione di persone ha trovato più rotture del legamento crociato anteriore fra chi assume testosterone come terapia sostitutiva. I risultati degli studi sono però molto diversi fra loro.", "Si tratta di un'associazione osservata, non di una causa dimostrata: chi segue una terapia con testosterone ne parla con il proprio medico."], "kw": "testosterone, legamento crociato, rottura, ricostruzione"}, "9": {"prof": ["Diabete e revisione del LCA a 5 anni: HR 0,77 (IC 95% 0,47-1,26) nella base TriNetX", "Coorte retrospettiva (Adv Ther, ottobre 2026; 73.951 LCA primari, 990 con diabete): dopo appaiamento per età, sesso e BMI (988 per gruppo) revisione 30/988 contro 38/988, HR 0,77 (IC 95% 0,47-1,26); nell'analisi di sensibilità senza procedure concomitanti HR 0,45 (IC 95% 0,08-2,45).", "Nota critica: dati di codifica, appaiamento solo su età, sesso e BMI, innesto e controllo glicemico non nell'abstract; l'analisi di sensibilità ha da 1 a 10 eventi per gruppo ed è muta."], "mix": ["Diabete e secondo intervento al crociato: nessun aumento del rischio nei primi cinque anni", "In una grande base di dati con quasi 74.000 ricostruzioni del legamento crociato anteriore, i pazienti con diabete non hanno avuto più reinterventi sullo stesso ginocchio nei cinque anni successivi rispetto a pazienti simili senza diabete: 30 su 988 contro 38 su 988.", "Nota sul limite: i dati vengono dai codici di fatturazione e non dicono come fosse controllato il diabete; l'intervallo di confidenza non esclude un modesto aumento del rischio."], "paz": ["Diabete e ricostruzione del crociato: nessun maggior rischio di secondo intervento nei primi cinque anni", "Uno studio su un'ampia raccolta di dati ha confrontato persone con e senza diabete dopo la ricostruzione del legamento crociato anteriore: nei cinque anni successivi il secondo intervento sullo stesso ginocchio non è risultato più frequente nelle persone con diabete.", "I dati non dicono nulla sul controllo del diabete né su altre complicanze: ciò che vale per un singolo paziente si decide con il medico."], "kw": "diabete, legamento crociato, reintervento, ricostruzione"}};
var ARTICLES=[{n:1,mono:"m-kssta",dot:"orange",sec:"res",j:"KSSTA",h:"LCM: l'allotrapianto di Achille ha più complicanze dell'autotrapianto hamstring, ma il confronto è indiretto",v:"Revisione sistematica PRISMA (livello III dichiarato) sulla ricostruzione del legamento collaterale mediale: 16 studi, 6 con allotrapianto di tendine d'Achille (107 pazienti, 4 studi con blocco osseo) e 10 con autotrapianto di hamstring (275 pazienti). Gli esiti riferiti dal paziente migliorano in entrambi i gruppi (p<0,05 in tutti gli studi con misure prima e dopo; IKDC medio 81,1 contro 78,8, Lysholm 86,8 contro 87,2). Le complicanze sono l'11,2% con l'allotrapianto e il 4,0% con l'hamstring, ma gli autori concludono che l'evidenza è indiretta e non basta a dire quale innesto sia superiore.",ax:"Sian, See, Alqeisi, Meena, Dalgleish, de Sa, Davies, D'Alessandro, Ng, Malik",date:"set 2026",meta:"revisione sistematica, 16 studi (6 allotrapianto d'Achille, 107 pazienti; 10 hamstring, 275 pazienti), sintesi narrativa · [livello III]",pmid:'42770603',doi:'10.1002/ksa.70625',journal:"Knee surgery, sports traumatology, arthroscopy",authors:"Sian R, See A, Alqeisi T, Meena A, Dalgleish S, de Sa D, Davies P, D'Alessandro P, Ng J, Malik SS",design:"Revisione sistematica secondo PRISMA (PubMed, Cochrane, Google Scholar, Scopus; ricerca dell'11 febbraio 2026) di studi su pazienti di almeno 16 anni con ricostruzione del LCM con hamstring o allotrapianto d'Achille. Rischio di bias valutato; per l'eterogeneità solo sintesi narrativa, nessuna metanalisi. Livello III dichiarato. Letto l'abstract su PubMed; testo completo non in PMC e non aperto.",pop:"16 studi: 6 con allotrapianto d'Achille (107 pazienti; 4 studi con blocco osseo) e 10 con autotrapianto di hamstring (275 pazienti). Età media 33,9 anni (allotrapianto) e 31,3 (hamstring); follow-up medio 37 e 29,1 mesi. Fissazione, tessuto allogenico, grado e fase della lesione: non riportati nell'abstract.",results:"IKDC medio postoperatorio 81,1 con allotrapianto contro 78,8 con hamstring; Lysholm 86,8 contro 87,2. Tre studi sull'allotrapianto e sei sull'hamstring riportano gli esiti prima e dopo: miglioramento significativo in tutti (p<0,05). Complicanze 11,2% con allotrapianto (2 fallimenti dell'innesto, 4 instabilità in valgo residue asintomatiche, 3 infezioni, 3 altre) contro 4,0% con hamstring (1 fallimento, 4 instabilità in valgo asintomatiche, 3 mobilizzazioni, 1 infezione, 2 rimozioni di mezzi di sintesi). Calcolo mio (12 su 107 contro 11 su 275; test/potenza.py): rischio relativo grezzo 2,80 (IC 95% 1,28-6,16), che somma studi con definizioni diverse di complicanza: un segnale, non una stima. Test fra i gruppi e intervalli di confidenza non riportati nell'abstract.",concl:"Gli autori: entrambi gli innesti migliorano in modo significativo gli esiti riferiti dal paziente; l'allotrapianto d'Achille ha un tasso di complicanze numericamente più alto, ma l'evidenza è indiretta e insufficiente per stabilire la superiorità di uno dei due.",limits:"Nessun confronto diretto: sei serie contro dieci, di centri e periodi diversi, quindi indicazione, tecnica e definizione di complicanza si confondono con il tipo di innesto · sintesi solo narrativa, senza metanalisi né test fra i gruppi · follow-up medio sotto i quattro anni, più breve con l'hamstring · tessuto allogenico e fissazione non descritti nell'abstract · testo completo non aperto (NON VERIFICATO oltre l'abstract).",perte:"Arancione perché tocca una tua tecnica: ricostruisci il collaterale mediale con allotrapianto. L'abstract non dice quale allotrapianto usi tu né se i tuoi casi siano acuti o cronici, e le serie sull'Achille sono solo sei: il segnale di più complicanze (11,2% contro 4,0%) è numerico, indiretto, e gli autori stessi lo dichiarano insufficiente. Non tocca le tensioni aperte. Cosa fare: nulla da cambiare; per un LCM cronico o inserito in una multilegamentosa tieni presente che l'hamstring autologo è un'alternativa documentata con meno complicanze riportate, senza prova di superiorità."},
{n:2,mono:"m-jeo",dot:"green",sec:"res",j:"J Exp Orthop",h:"Lesione radiale obliqua del menisco laterale nel LCA: la sutura laterale-laterale riporta l'estrusione a livelli simili",v:"Coorte retrospettiva (Hirosaki, Giappone; livello III): su 609 LCA primari (2016-2023), 34 pazienti con lesione radiale obliqua del menisco laterale trattata con sutura laterale-laterale e 27 con lesione longitudinale posteriore trattata con sutura all-inside. L'estrusione coronale preoperatoria è maggiore nella lesione radiale obliqua (1,71±1,31 contro 0,32±0,61 mm; p<0,001), scende di circa 0,6 mm dopo la sutura e a un anno è simile fra i gruppi; esiti clinici simili a un anno e al follow-up finale.",ax:"Ishibashi K., Ishibashi H.K., Sasaki, Kimura, Ishibashi Y.",date:"set 2026",meta:"coorte retrospettiva, 34 lesioni radiali oblique contro 27 longitudinali, tutte con LCA, RM a 6 e 12 mesi · [livello III]",pmid:'42769800',doi:'10.1002/jeo2.70916',journal:"Journal of experimental orthopaedics",authors:"Ishibashi K, Ishibashi HK, Sasaki E, Kimura Y, Ishibashi Y",design:"Coorte retrospettiva con confronto interno (livello III dichiarato) su 609 LCA primari del 2016-2023: 34 lesioni radiali oblique del menisco laterale (confermate in artroscopia) con sutura laterale-laterale e 27 longitudinali posteriori con sutura all-inside; RM a 6 mesi e a un anno. Estrusione coronale e sagittale, esiti clinici, stabilità e KOOS a confronto; regressione multivariata sul cambio di estrusione e curva ROC. Letto l'abstract su PubMed (testo in PMC, non aperto).",pop:"61 pazienti sottoposti a LCA primario con sutura del menisco laterale (34 e 27). Età, sesso, tipo di innesto e tecnica del LCA: non riportati nell'abstract. La lesione radiale obliqua è il 7,4% dei casi, secondo l'abstract (denominatore non chiarito).",results:"Estrusione coronale preoperatoria 1,71±1,31 mm nella lesione radiale obliqua contro 0,32±0,61 mm nella longitudinale (p<0,001). Dopo la sutura l'estrusione coronale migliora di circa 0,6 mm ed è simile fra i gruppi a un anno; l'estrusione sagittale aumenta leggermente in entrambi; esiti clinici simili a un anno e al follow-up finale. L'estrusione coronale preoperatoria predice il cambio a un anno (coefficiente -0,514; p<0,001) e, oltre 1,0 mm, distingue la lesione radiale obliqua (AUC 0,787; p<0,001). Valori degli esiti clinici, rotture e reinterventi della sutura: non riportati nell'abstract.",concl:"Gli autori: la sutura laterale-laterale della lesione radiale obliqua durante il LCA riduce l'estrusione coronale a un anno fino a valori simili a quelli della lesione longitudinale, con esiti clinici simili; la sostengono come strategia affidabile di conservazione del menisco.",limits:"Il gruppo di confronto è un altro tipo di lesione, non un'altra terapia della stessa lesione: nessun confronto con meniscectomia parziale o con non trattamento · retrospettivo, 34 contro 27: «esiti simili» non è prova di equivalenza · l'estrusione è un surrogato radiologico a un anno; rotture della sutura e reinterventi non sono nell'abstract · un solo centro; tecnica del LCA e innesto non riportati.",perte:"Tocca le tue suture meniscali in corso di LCA. Lo studio dice che la sutura laterale-laterale riporta l'estrusione a valori simili a quelli di una lesione longitudinale suturata, non che sia superiore a un'alternativa. Non tocca le tensioni aperte (la tensione 3 riguarda la radice mediale, non il menisco laterale). Cosa fare: nulla da cambiare nella tecnica; se ti trovi davanti a una lesione radiale laterale, l'estrusione coronale preoperatoria in risonanza (soglia di 1,0 mm in questa serie) è una misura da riportare."},
{n:3,mono:"m-gray",dot:"green",sec:"res",j:"Am J Sports Med",h:"Slope tibiale: la pendenza laterale governa la traslazione anteriore, la differenza laterale-mediale la rotazione interna",v:"Studio biomeccanico di laboratorio su 8 ginocchia di cadavere (Imperial College, Londra): osteotomie unicondilari con cunei stampati in 3D modificano in modo indipendente la pendenza tibiale posteriore mediale e laterale (da -5° a +10°) sotto carico assiale di 500 N, a 0° e 20° di flessione. +10° di pendenza laterale aumenta la traslazione tibiale anteriore (p=0,012), quella mediale no (p>0,99). La rotazione interna dipende dalla differenza fra pendenza laterale e mediale: a 0° di flessione +10° di differenza dà 7,6° di rotazione in più (p=0,015).",ax:"Nejima, Holt, van Arkel, Metcalfe, Smith, Amis",date:"set 2026",meta:"studio controllato di laboratorio, 8 ginocchia di cadavere, osteotomie unicondilari di slope · [cadavere]",pmid:'42770555',doi:'10.1177/03635465261480902',journal:"The American journal of sports medicine",authors:"Nejima S, Holt J, van Arkel R, Metcalfe A, Smith N, Amis A",design:"Studio controllato di laboratorio su 8 ginocchia di cadavere in una macchina di compressione e torsione. Osteotomie unicondilari con guida su misura e cunei stampati in 3D modificano la pendenza tibiale posteriore mediale e laterale in modo indipendente (da -5° a +10°), preservando legamenti e radici meniscali; cinematica con tracciamento ottico sotto 500 N a 0° e 20° di flessione; ANOVA a misure ripetute e correlazione di Pearson. Letto l'abstract su PubMed; testo completo non in PMC e non aperto.",pop:"8 preparati anatomici; età, sesso e stato del LCA dei preparati: non riportati nell'abstract. Nessun paziente.",results:"+10° di pendenza laterale aumenta in modo significativo la traslazione anteriore della tibia (p=0,012); la pendenza mediale no (p>0,99). A 0° di flessione la sola pendenza laterale o mediale non cambia la rotazione in modo significativo, mentre +10° di differenza dà 7,6° di rotazione interna in più (p=0,015). A 20° di flessione variare di ±10° le singole pendenze cambia la rotazione (p<0,036). Le maggiori differenze di rotazione correlano con valori opposti della differenza fra le pendenze (coefficiente 0,960; p=0,0006; il tipo di coefficiente non si legge nell'abstract). Dimensioni dell'effetto in gradi e intervalli di confidenza per la traslazione: non riportati nell'abstract.",concl:"Gli autori: la pendenza laterale è il determinante principale della traslazione anteriore e la differenza fra le pendenze quello della rotazione interna sotto carico assiale; suggeriscono che una correzione differenziale della pendenza possa ottimizzare la rotazione tibio-femorale.",limits:"Cadavere: nessuna forza muscolare, nessuna guarigione, nessun paziente · 8 preparati e solo due angoli di flessione, carico statico · le osteotomie unicondilari sono un modello sperimentale, non la tecnica con cui si corregge la slope in clinica · stato del LCA dei preparati non riportato nell'abstract · la proposta di correzione differenziale è un'ipotesi degli autori, mai provata sui pazienti.",perte:"Tocca la correzione di slope e il ruolo della pendenza nel LCA. È un dato biomeccanico su cadavere: la pendenza laterale conta per la traslazione anteriore, la differenza laterale-mediale per la rotazione. Nessun paziente è stato operato con una correzione differenziale. Non tocca le tensioni aperte. Cosa fare: nulla da cambiare; quando misuri la slope prima di un'osteotomia o di una revisione di LCA, annota separatamente la pendenza mediale e laterale e la loro differenza, non solo il valore medio."},
{n:4,mono:"m-arth",dot:"green",sec:"res",j:"Arthroscopy",h:"Osteotomia tibiale alta aperta: l'artrosi femororotulea progredisce in più della metà dei casi, ma non pesa sugli esiti a lungo termine",v:"Coorte retrospettiva consecutiva (Fukuoka, Giappone; livello IV): 168 ginocchia dopo osteotomia tibiale alta aperta (2007-2014) per artrosi mediale o osteonecrosi, follow-up medio 12,2 anni (minimo 10). Sopravvivenza a 10 anni 91,3% (conversione a protesi), nessuna conversione per artrosi femororotulea. La progressione femororotulea (aumento di almeno un grado Kellgren-Lawrence) è nel 55,4% (93/168), ma i punteggi KOOS-femororotuleo (68,5 contro 69,8; p=0,533) e rotuleo HSS (89,0 contro 91,0; p=0,179) non differiscono fra progressione e non progressione.",ax:"Shimada, Maeyama, Akiyama, Gomi, Goshima, Hirano, Ishimatsu, Yamamoto",date:"set 2026",meta:"coorte retrospettiva, 168 ginocchia dopo osteotomia tibiale alta aperta, follow-up medio 12,2 anni · [livello IV]",pmid:'42768777',doi:'10.1002/arj.70617',journal:"Arthroscopy: the journal of arthroscopic & related surgery",authors:"Shimada T, Maeyama A, Akiyama T, Gomi N, Goshima K, Hirano F, Ishimatsu T, Yamamoto T",design:"Coorte retrospettiva di pazienti consecutivi operati di osteotomia tibiale alta aperta per artrosi mediale o osteonecrosi tra il 2007 e il 2014, con almeno 10 anni di follow-up; esclusi i pazienti con dati radiografici o punteggi incompleti. Ginocchia divise in progressione e non progressione dell'artrosi femororotulea (aumento di almeno un grado Kellgren-Lawrence). Esiti: KOOS-femororotuleo e punteggio rotuleo HSS, confrontati con t di Student o Mann-Whitney; predittori con regressione logistica multivariata; sopravvivenza con la conversione a protesi come evento. Letto l'abstract su PubMed; testo completo non in PMC e non aperto.",pop:"168 ginocchia, follow-up medio 12,2 anni (da 10,0 a 16,9). Età, sesso, entità della deformità e quota di pazienti esclusi per dati incompleti: non riportati nell'abstract.",results:"Sopravvivenza a 10 anni 91,3%; nessun ginocchio convertito a protesi per artrosi femororotulea. Progressione femororotulea nel 55,4% (93/168). KOOS-femororotuleo 68,5 contro 69,8 (p=0,533); punteggio rotuleo HSS 89,0 contro 91,0 (p=0,179). Predittori indipendenti di progressione: angolo di correzione (OR 1,361; p=0,004) e grado Kellgren-Lawrence femororotuleo preoperatorio (OR 0,241; p=0,002). Intervalli di confidenza degli OR e unità dell'angolo di correzione: non riportati nell'abstract.",concl:"Gli autori: dopo osteotomia tibiale alta aperta l'artrosi femororotulea progredisce, ma non ha peggiorato gli esiti clinici femororotulei a 12,2 anni di follow-up medio.",limits:"Retrospettivo, livello IV, con esclusione dei casi a dati incompleti (rischio di selezione; i perduti al follow-up non sono quantificati) · la progressione è misurata con un salto di grado Kellgren-Lawrence, misura grossolana · nessun gruppo di controllo non operato: non dice quanta progressione ci sarebbe senza osteotomia · gli OR sono senza intervallo di confidenza nell'abstract · testo completo non aperto.",perte:"Tocca le osteotomie correttive. Per te conta come dato da dare al paziente: dopo una osteotomia tibiale alta aperta la femororotulea peggiora spesso alla radiografia, ma in questa serie non ha pesato sui sintomi rotulei a 12 anni. L'angolo di correzione più ampio predice la progressione; un grado preoperatorio femororotuleo più alto si associa a meno progressione (spiegazione mia, non degli autori: probabile effetto soffitto). Non tocca le tensioni aperte. Cosa fare: nel consenso per una osteotomia aperta con correzione ampia puoi dichiarare la progressione radiografica femororotulea come frequente e, in questa serie, non legata ai sintomi."},
{n:5,mono:"m-arth",dot:"green",sec:"res",j:"Arthroscopy",h:"Instabilità rotulea con displasia trocleare: una sTTTG più alta si associa a esiti più favorevoli dopo MPFL e troclearplastica",v:"Coorte retrospettiva (Mannheim e Pforzheim, Germania; livello IV): 101 pazienti (età media 22,7±6,6 anni; 72 donne) con instabilità rotulea laterale recidivante e displasia trocleare di alto grado (Dejour B-D), operati nel 2016-2018 con ricostruzione del MPFL e troclearplastica di approfondimento, follow-up medio 32,3±8,7 mesi. Una distanza sagittale tubercolo tibiale-troclea (sTTTG) preoperatoria più alta si associa a BPII 2.0 più alto (β=0,98; p=0,019), meno dolore (β=-0,10; p=0,048) e miglior funzione (β=0,088; p=0,014); dopo correzione per i confondenti restano significative (BPII 2.0 β=0,91; p=0,037). Il potere esplicativo è però minimo: R² corretti da 0,03 a 0,06.",ax:"Schmidt, Navas, Zimmermann, Oudeh, Lattermann, Balcarek",date:"set 2026",meta:"coorte retrospettiva, 101 pazienti con MPFL e troclearplastica, follow-up medio 32 mesi · [livello IV]",pmid:'42791236',doi:'10.1002/arj.70552',journal:"Arthroscopy: the journal of arthroscopic & related surgery",authors:"Schmidt S, Navas L, Zimmermann F, Oudeh AEN, Lattermann C, Balcarek P",design:"Coorte retrospettiva su pazienti operati tra il 2016 e il 2018 di ricostruzione del MPFL con troclearplastica di approfondimento per instabilità rotulea laterale recidivante (almeno 2 lussazioni o sintomi persistenti dopo almeno 6 mesi di terapia conservativa) e displasia trocleare di alto grado (Dejour B-D); follow-up minimo 18 mesi. La sTTTG misurata su RM assiale T2 come distanza fra cartilagine trocleare e tuberosità tibiale, riferita all'asse condilare posteriore. Esiti con BPII 2.0, scale numeriche per dolore e funzione; regressione lineare univariata e multivariata corretta per età, BMI, indice di Caton-Deschamps, classe di Dejour e TT-TG. Letto l'abstract su PubMed; testo completo non in PMC e non aperto.",pop:"101 pazienti (29 uomini e 72 donne; età 22,7±6,6 anni; BMI 24,3±4,9), follow-up 32,3±8,7 mesi (da 19 a 60). Tecnica di fissazione del MPFL, innesto e interventi associati sull'apparato estensore: non riportati nell'abstract.",results:"sTTTG più alta e BPII 2.0: β=0,98 (p=0,019); e dolore: β=-0,10 (p=0,048); funzione: β=0,088 (p=0,014). Dopo correzione per i confondenti: funzione β=0,096 (p=0,011); dolore β=-0,11 (p=0,044); BPII 2.0 β=0,91 (p=0,037). Miglioramento clinicamente rilevante (soglia calcolata sulla coorte): 89% per il BPII 2.0, 77% per il dolore, 88% per la funzione. R² corretti da 0,03 a 0,06. Unità di misura della sTTTG per il coefficiente e intervalli di confidenza dei β: non riportati nell'abstract.",concl:"Gli autori: una sTTTG preoperatoria più alta si associa a miglior recupero funzionale, meno dolore e miglior qualità di vita femororotulea dopo troclearplastica di approfondimento con MPFL.",limits:"Potere esplicativo molto basso (R² corretti 0,03-0,06): la sTTTG spiega al più il 6% della variabilità degli esiti, quindi non è un criterio di scelta · retrospettivo, livello IV, solo displasia di alto grado, senza gruppo con solo MPFL né con la sola troclearplastica · il verso dell'associazione (sTTTG più alta, esiti più favorevoli) è controintuitivo e senza spiegazione nell'abstract · intervalli di confidenza non riportati · testo completo non aperto.",perte:"Tocca il MPFL, che ricostruisci con ancore FiberTak onlay. Nel tuo profilo la troclearplastica non compare fra le procedure, e questo lavoro riguarda la combinazione nella displasia di alto grado, con un predittore che spiega pochissimo. Non tocca le tensioni aperte. Cosa fare: nulla da cambiare; per un paziente con displasia trocleare di alto grado la sTTTG su RM è una misura in più da riportare, non un criterio di scelta dell'intervento."},
{n:6,mono:"m-jrs",dot:"green",sec:"res",j:"J Arthroplasty",h:"TKA robotica: la sensibilità al dolore preoperatoria pesa più dell'allineamento scelto sugli esiti a due anni",v:"Sottostudio di un RCT prospettico in singolo cieco (Auckland, Nuova Zelanda; livello I dichiarato): 244 pazienti con TKA robotica randomizzati ad allineamento funzionale (123) o meccanico (121); sensibilità al dolore preoperatoria misurata con il Pain Sensitivity Questionnaire (PSQ). A due anni il PSQ predice in negativo il Forgotten Joint Score (p=0,02) e l'Oxford Knee Score (p<0,01), l'allineamento no. Nei pazienti a bassa sensibilità l'allineamento funzionale dà un FJS più alto (74,9±25,8 contro 61,9±31,4; p=0,03); in quelli ad alta sensibilità non c'è differenza (66,8±25,0 contro 65,8±29,5; p=0,80). Analisi esplorative di sottogruppo, come dichiarano gli autori.",ax:"Kawaguchi, Tay, Farrington, van Rooyen, Bayan, Young",date:"set 2026",meta:"sottostudio di RCT in singolo cieco, 244 TKA robotiche (123 funzionale, 121 meccanico), esiti a 2 anni · [livello I dichiarato, analisi esplorativa]",pmid:'42772427',doi:'10.1016/j.arth.2026.09.037',journal:"The Journal of arthroplasty",authors:"Kawaguchi K, Tay ML, Farrington WJ, van Rooyen R, Bayan A, Young SW",design:"Sottostudio di un RCT prospettico in singolo cieco: 244 pazienti con TKA robotica assegnati ad allineamento funzionale (123) o meccanico (121). Sensibilità al dolore misurata prima dell'intervento con il Pain Sensitivity Questionnaire; a due anni Forgotten Joint Score (FJS) e Oxford Knee Score (OKS). Regressioni multivariate a passi corrette per fattori demografici e radiografici; pazienti stratificati in alta (PSQ≥5,2) e bassa sensibilità e confronto funzionale contro meccanico nei due strati. Letto l'abstract su PubMed; testo completo non in PMC e non aperto.",pop:"244 pazienti con TKA robotica (123 e 121); PSQ iniziale simile nei gruppi (5,7±1,9 contro 5,6±1,8; p=0,58). Marca del robot, protesi, età e sesso: non riportati nell'abstract.",results:"PSQ predittore negativo di FJS (p=0,02) e di OKS (p<0,01); l'allineamento non lo è. Bassa sensibilità al dolore: FJS 74,9±25,8 con allineamento funzionale contro 61,9±31,4 con meccanico (p=0,03). Alta sensibilità: FJS 66,8±25,0 contro 65,8±29,5 (p=0,80). Coefficienti di regressione, dimensioni dell'effetto e intervalli di confidenza: non riportati nell'abstract.",concl:"Gli autori: la sensibilità al dolore preoperatoria influenza gli esiti riferiti più della filosofia di allineamento; la differenza a favore dell'allineamento funzionale compare solo nei pazienti a bassa sensibilità, ma l'analisi è esplorativa e va confermata.",limits:"Analisi di sottogruppo esplorative, senza potenza dichiarata e con p non corretti per i confronti multipli (nell'abstract non è dichiarata alcuna correzione) · soglia di 5,2 per il PSQ e suo metodo di scelta non nell'abstract · solo esiti riferiti dal paziente (FJS e OKS) a due anni · marca del robot non riportata: NON VERIFICATO che coincida con il tuo VELYS · testo completo non aperto.",perte:"Tocca la tua protesi totale con robot, ma l'abstract non dice quale robot sia stato usato: NON VERIFICATO che sia il tuo sistema. Il dato per te è che la sensibilità al dolore preoperatoria spiega gli esiti riferiti più dell'allineamento scelto. Non tocca le tensioni aperte. Cosa fare: nulla da cambiare nel piano di allineamento; è un'analisi esplorativa di sottogruppo."},
{n:7,mono:"m-gray",dot:"green",sec:"res",j:"J Knee Surg",h:"Multilegamentose in età pediatrica: quattro studi, soprattutto da sport; angolo posterolaterale e LCP i più coinvolti",v:"Revisione sistematica (Washington University, St Louis; livello IV) di 4 studi, 142 pazienti di età fino a 18 anni (media 16,2), follow-up medio ponderato 41,2 mesi. Meccanismo sportivo nel 70,6% (96/136); angolo posterolaterale coinvolto nel 71,1% (101/142), LCP nel 66,2% (94/142), LCA nel 57,7% (82/142). Ricostruzione in 96,0% degli angoli posterolaterali, 98,9% dei LCP, 98,8% dei LCA e 48,4% dei LCM; riparazione nel 38,7% dei LCM. Complicanze nel 36% (19/53; rigidità 11,3%, fallimento della ricostruzione 5,7%) e revisione nel 7,5% (4/53).",ax:"Froemming, Touhey, Wang, Knapik",date:"ott 2026",meta:"revisione sistematica, 4 studi, 142 pazienti ≤18 anni, follow-up medio ponderato 41,2 mesi · [livello IV]",pmid:'42887882',doi:'10.1055/a-2982-7395',journal:"The journal of knee surgery",authors:"Froemming CJ, Touhey DC, Wang SJ, Knapik DM",design:"Revisione sistematica: PubMed, Embase e Cochrane Library dall'inizio a gennaio 2026; inclusi studi in inglese su pazienti di 18 anni o meno trattati per lesioni multilegamentose del ginocchio, con eziologia, tecnica chirurgica, complicanze, reinterventi ed esiti riferiti. Sintesi descrittiva con medie ponderate; livello IV dichiarato. Letto l'abstract su PubMed; testo completo non in PMC e non aperto.",pop:"142 pazienti in 4 studi, età media ponderata 16,2 anni (da 6 a 18), BMI medio 24,9 kg/m² (da 17,9 a 41,6), 69,7% maschi. Maturità scheletrica, tecnica di ricostruzione e innesto: non riportati nell'abstract.",results:"Sport 70,6% (96/136). Strutture lese: angolo posterolaterale 71,1% (101/142), LCP 66,2% (94/142), LCA 57,7% (82/142). Ricostruzione: angolo posterolaterale 96,0% (97/101), LCP 98,9% (93/94), LCA 98,8% (81/82), LCM 48,4% (15/31); riparazione: angolo posterolaterale 4,0%, LCP 1,1%, LCA 1,2%, LCM 38,7% (12/31). Complicanze 36% (19/53), le più frequenti rigidità 11,3% (6/53) e fallimento della ricostruzione 5,7% (3/53); revisione 7,5% (4/53). Intervalli di confidenza non riportati nell'abstract.",concl:"Gli autori: le multilegamentose pediatriche seguono soprattutto un trauma sportivo, con angolo posterolaterale e LCP i più coinvolti; si ricostruisce più spesso di quanto si ripari, con complicanze nel 36% e revisione nel 7,5% dei pazienti.",limits:"Solo 4 studi e 142 pazienti, con età da 6 a 18 anni: immaturi e quasi maturi si mescolano · complicanze e revisioni note solo per 53 pazienti su 142, quindi le percentuali poggiano su un terzo del campione · nessun confronto fra riparazione e ricostruzione né fra tempi di intervento · livello IV; maturità scheletrica e tecnica non riportate · testo completo non aperto.",perte:"Tocca le multilegamentose e il LCA nell'adolescente (dai 14 anni in su, nel tuo perimetro). Il campione va da 6 a 18 anni: solo una parte somiglia ai tuoi pazienti. Il dato da tenere è l'ordine di grandezza di rigidità e complicanze, calcolato su 53 pazienti. Non tocca le tensioni aperte. Cosa fare: nulla da cambiare; cita le percentuali con la cautela del denominatore."},
{n:8,mono:"m-gray",dot:"gray",sec:"res",j:"Sports Health",h:"Testosterone e LCA: più rotture a due anni con la terapia sostitutiva, ma eterogeneità altissima",v:"Revisione sistematica e metanalisi (livello III dichiarato; Embase, Ovid MEDLINE e PubMed fino al 14 marzo 2026): 7 studi, 1.178.891 pazienti, di cui 589.436 in terapia sostitutiva con testosterone. La terapia si associa a più rotture primarie del LCA entro 2 anni (OR 2,83; IC 95% 1,74-4,62; eterogeneità 95,4%), non a più revisioni a 2 anni (OR 1,04; IC 95% 0,84-1,29; eterogeneità 0%). Un RCT riporta più massa magra precoce con la terapia, senza differenze di forza o di PROMs.",ax:"Duru, Lee, Vivekanantha, Bouchard, Alzobi, Alkhatib, Zikria, Hantouly, Khan",date:"ott 2026",meta:"revisione sistematica con metanalisi, 7 studi, 1.178.891 pazienti, esiti a 2 anni · [livello III]",pmid:'42881560',doi:'10.1177/19417381261486660',journal:"Sports health",authors:"Duru DO, Lee DKR, Vivekanantha P, Bouchard MD, Alzobi O, Alkhatib L, Zikria BA, Hantouly A, Khan M",design:"Revisione sistematica con metanalisi a effetti casuali: Embase, Ovid MEDLINE e PubMed dall'inizio al 14 marzo 2026; inclusi studi su terapia sostitutiva con testosterone o livelli endogeni in rapporto all'incidenza di rottura del LCA o agli esiti dopo ricostruzione; OR cumulati per rottura e revisione; qualità con MINORS e Cochrane RoB 2.0, certezza con GRADE. Livello III dichiarato. Letto l'abstract su PubMed; testo completo non in PMC e non aperto.",pop:"7 studi, 1.178.891 pazienti (589.436 in terapia sostitutiva con testosterone). Tipo di studio per ciascuno, età, sesso, indicazione della terapia e dose: non riportati nell'abstract.",results:"Rottura primaria del LCA entro 2 anni con terapia sostitutiva: OR 2,83 (IC 95% 1,74-4,62; eterogeneità 95,4%), con risultati concordi nelle analisi per sesso. Revisione del LCA a 2 anni: OR 1,04 (IC 95% 0,84-1,29; eterogeneità 0%). Un RCT: più massa magra precoce con la terapia, senza differenze di forza o PROMs. Testosterone endogeno: rischio di rottura più alto con livelli più alti negli uomini e con livelli più bassi nelle donne; livelli più alti non peggiorano PROMs né complicanze dopo ricostruzione. Certezza GRADE dei singoli esiti: non riportata nell'abstract.",concl:"Gli autori: la terapia sostitutiva con testosterone si associa a più rotture del LCA a 2 anni ma non sembra influire sulle revisioni a 2 anni; il testosterone endogeno può influire sulla suscettibilità alla lesione in modo dipendente dal sesso, senza compromettere il recupero dopo ricostruzione.",limits:"Eterogeneità del 95,4% sulla stima principale: l'OR cumulato di 2,83 non è una stima attendibile di un unico effetto · studi osservazionali, con confondimento per indicazione (chi assume testosterone differisce da chi non lo assume) · numeri dell'ordine del milione fanno pensare a basi di dati amministrative, ma l'abstract non lo dice (NON VERIFICATO) · orizzonte di soli 2 anni · testo completo non aperto.",perte:"Nel perimetro, non tocca la tua tecnica né le tensioni aperte. Per la pratica: l'uso di testosterone è un'informazione da registrare nell'anamnesi; il dato non cambia indicazione o tipo di intervento, e gli esiti dopo ricostruzione non risultano peggiori. Nessuna azione."},
{n:9,mono:"m-gray",dot:"gray",sec:"res",j:"Adv Ther",h:"LCA e diabete: nessun aumento del rischio di revisione a cinque anni nella grande base TriNetX",v:"Coorte retrospettiva su rete federata TriNetX (53 organizzazioni sanitarie): 73.951 LCA primari (2005-2025), 990 in pazienti con diabete (1,3%). Dopo appaiamento 1:1 per età, sesso e BMI (988 per gruppo) la revisione è 30/988 con diabete contro 38/988 senza (HR 0,77; IC 95% 0,47-1,26). Nell'analisi di sensibilità che esclude le procedure concomitanti sui tessuti molli (243 per gruppo) gli eventi sono da 1 a 10 per gruppo (HR 0,45; IC 95% 0,08-2,45).",ax:"Eleftheriadou, Anson, Fozo, Khan, Al-Hourani, Alam",date:"ott 2026",meta:"coorte retrospettiva su base federata, 73.951 LCA primari, 988 per gruppo dopo appaiamento, follow-up fino a 5 anni · [coorte con controllo]",pmid:'42886432',doi:'10.1007/s12325-026-03815-w',journal:"Advances in therapy",authors:"Eleftheriadou A, Anson M, Fozo Z, Khan S, Al-Hourani K, Alam U",design:"Coorte retrospettiva osservazionale sulla rete di dati sanitari TriNetX (53 organizzazioni): LCA primari fra il 5 agosto 2005 e il 4 agosto 2025; evento la successiva ricostruzione del LCA sullo stesso ginocchio, con follow-up fino a 5 anni. Diabete di tipo 1 o 2 contro assenza di diabete dopo appaiamento per punteggio di propensione 1:1 su età, sesso e BMI; Kaplan-Meier e hazard ratio; analisi di sensibilità senza meniscectomia, sutura o trapianto meniscale e altre ricostruzioni legamentose concomitanti. Letto l'abstract su PubMed; testo completo non in PMC e non aperto.",pop:"73.951 pazienti con LCA primario, di cui 990 con diabete; dopo l'appaiamento 988 per gruppo. Tipo di innesto, tecnica, emoglobina glicata, durata e controllo del diabete: non riportati nell'abstract.",results:"Revisione a 5 anni: 30/988 con diabete contro 38/988 senza; HR 0,77 (IC 95% 0,47-1,26), non significativo. Sensibilità senza procedure concomitanti (243 per gruppo, da 1 a 10 eventi per gruppo, conteggi esatti non riportati): HR 0,45 (IC 95% 0,08-2,45). Con test/potenza.py: rischio relativo grezzo 0,79 (IC 95% 0,49-1,26).",concl:"Gli autori: il diabete non si associa a un rischio aumentato di revisione del LCA entro 5 anni dalla ricostruzione primaria, anche nell'analisi di sensibilità; i risultati vanno letti con i limiti dello studio e non sostituiscono la valutazione individuale del rischio.",limits:"Dati di codifica (base federata): la revisione è un nuovo codice di ricostruzione del LCA sullo stesso ginocchio, senza conferma clinica · appaiamento solo su età, sesso e BMI; innesto, tecnica, controllo glicemico e complicanze (infezione, rigidità) non nell'abstract · l'IC principale (0,47-1,26) non esclude né una riduzione né un aumento di circa un quarto del rischio di revisione · l'analisi di sensibilità, con da 1 a 10 eventi per gruppo, è muta · follow-up massimo 5 anni.",perte:"Nel perimetro, non tocca la tua tecnica né le tensioni aperte. Per il colloquio pre-operatorio: nella grande base TriNetX il diabete non risulta un fattore di revisione del LCA a 5 anni, ma l'intervallo non esclude un aumento fino a circa il 26% e non dice nulla su infezione o rigidità. Nessuna azione."}];
var SUGGQ=[{"k": "kol", "n": "Peter Balcarek (Arcus Sportklinik, Pforzheim, Germania)", "w": "Germania: ultimo firmatario dello studio sulla sTTTG dopo MPFL e troclearplastica (PMID 42791236; afferenza letta nei metadati PubMed). Corrispondenza tecnica con la ricostruzione del MPFL, che esegui con ancore FiberTak onlay. Sostituisce Peter D. Fabricant (16 ottobre; nessun segnale dell'utente arrivato per farla ruotare)."}];
var BRIEF_TEXT="Sabato 17 ottobre. Oggi nove lavori, nessuna scheda rossa e una arancione. Nessun richiamo di dispositivi nuovo e nessuna ritrattazione che ti riguardi. Il lavoro del giorno è una revisione sistematica sulla ricostruzione del legamento collaterale mediale, ed è arancione perché tocca una tecnica che esegui, l'allotrapianto. Sedici studi, sei con allotrapianto di tendine d'Achille e dieci con autotrapianto di hamstring: i punteggi migliorano in modo significativo in entrambi i gruppi, ma le complicanze sono l'undici virgola due per cento con l'allotrapianto contro il quattro per cento con l'hamstring. Il confronto è però indiretto, fra serie diverse, e gli autori dicono che non basta per stabilire quale innesto sia superiore. Poi cinque lavori sulle tue tecniche. Una coorte giapponese sulla sutura laterale-laterale delle lesioni radiali oblique del menisco laterale durante il crociato: l'estrusione scende di circa sei decimi di millimetro e torna simile a quella delle lesioni longitudinali, ma i gruppi sono di trentaquattro e ventisette pazienti. Uno studio su cadavere sulla pendenza tibiale: la pendenza laterale governa la traslazione anteriore e la differenza fra laterale e mediale la rotazione interna. Una coorte di centosessantotto osteotomie tibiali alte aperte: l'artrosi femororotulea progredisce in più della metà dei casi, ma i punteggi rotulei a circa dodici anni non cambiano. Una coorte sul legamento patello-femorale mediale con troclearplastica, dove una distanza sagittale maggiore si associa a esiti più favorevoli, ma il modello spiega pochissimo. E un sottostudio di un trial sulla protesi totale robotica: la sensibilità al dolore pesa più dell'allineamento scelto; è un'analisi esplorativa e non so se il robot sia il tuo. Poi tre lavori di contesto: la revisione sulle multilegamentose pediatriche, quattro studi e centoquarantadue pazienti; la metanalisi sul testosterone, che associa la terapia a più rotture del crociato a due anni ma con un'eterogeneità altissima; e la coorte sul diabete, senza aumento di rischio di revisione del crociato a cinque anni nella base TriNetX. Nessuna tensione si è mossa oggi. Nella seconda pagina dieci brevi e tre proposte fuori dal solito, fra cui un robot cinese a piattaforma aperta per la protesi monocompartimentale.";
var BRIEF_DIALOGO=[{"chi": "A", "t": "Sabato diciassette ottobre. Nove lavori, nessuna scheda rossa e una arancione. Nessun richiamo nuovo di dispositivi e nessuna ritrattazione che ti riguardi."}, {"chi": "B", "t": "Qual è il lavoro del giorno?"}, {"chi": "A", "t": "Una revisione sistematica sulla ricostruzione del legamento collaterale mediale: allotrapianto di tendine d'Achille contro autotrapianto di hamstring. È arancione perché tocca una tecnica che esegui."}, {"chi": "B", "t": "E cosa trova?"}, {"chi": "A", "t": "Sedici studi. In entrambi i gruppi i punteggi migliorano in modo significativo. Le complicanze sono l'undici virgola due per cento con l'allotrapianto e il quattro per cento con l'hamstring, senza intervalli di confidenza nell'abstract."}, {"chi": "B", "t": "Quindi l'allotrapianto va messo da parte?"}, {"chi": "A", "t": "No, e qui sta il limite. Sono sei serie contro dieci, di centri diversi, nessuna confronta direttamente i due innesti, e gli autori parlano di evidenza indiretta, insufficiente per dire quale sia superiore."}, {"chi": "B", "t": "Per la mia pratica cosa cambia?"}, {"chi": "A", "t": "Niente. Per un collaterale cronico o dentro una multilegamentosa tieni presente che l'hamstring è un'alternativa documentata, senza prova di superiorità."}, {"chi": "B", "t": "Gli altri lavori sulle mie tecniche?"}, {"chi": "A", "t": "Cinque. Sul menisco laterale, la sutura laterale-laterale delle lesioni radiali oblique durante il crociato riporta l'estrusione a livelli simili alle lesioni longitudinali, ma con gruppi piccoli. Su cadavere, la pendenza tibiale laterale governa la traslazione anteriore e la differenza fra laterale e mediale la rotazione interna."}, {"chi": "B", "t": "E osteotomia e rotula?"}, {"chi": "A", "t": "Dopo osteotomia tibiale alta aperta l'artrosi femororotulea progredisce in più della metà dei casi, ma i punteggi rotulei a dodici anni non cambiano. Sul legamento patello-femorale mediale con troclearplastica, una distanza sagittale maggiore si associa a esiti più favorevoli, ma il modello spiega pochissimo."}, {"chi": "B", "t": "E la protesi robotica?"}, {"chi": "A", "t": "Un sottostudio di un trial: la sensibilità al dolore preoperatoria pesa più dell'allineamento scelto. È un'analisi esplorativa e l'abstract non dice quale robot fosse, quindi per il tuo VELYS non si può concludere nulla. Poi tre lavori di contesto: multilegamentose pediatriche, testosterone e crociato, diabete e revisione del crociato. Nessuna tensione si è mossa oggi."}];
